/** Auto-generated for round 50 */
export const QUIZ_ITEMS = [
  { id: "1315", section: "الحج والعمرة", category: "الحج", level: "سهل", question: "ما أركان الحج؟", answer: "الإحرام والوقوف بعرفة وطواف الإفاضة والسعي بين الصفا والمروة", explanation: "يُستفاد منه في باب الحج.", reference: "مراجع سُنّة" },
  { id: "1316", section: "الحج والعمرة", category: "الحج", level: "متوسط", question: "ما الميقات المكاني لأهل المدينة النبوية؟", answer: "ذو الحُلَيفة (أبيار علي)، ويُحرم منه أهل المدينة ومن مرّ به من غيرهم، وهو أبعد المواقيت عن مكة", explanation: "يُستفاد منه في باب الحج.", reference: "مراجع سُنّة" },
  { id: "1317", section: "الحج والعمرة", category: "الحج", level: "متوسط", question: "ما طواف الإفاضة؟", answer: "طواف الإفاضة (طواف الزيارة): ركن من أركان الحج لا يصحّ الحج بتركه ولا يُجبر بدم — بخلاف الواجب الذي يُجبر بدم — ووقته يوم النحر وما بعده، بعد الوقوف بعرفة. وأصله قوله تعالى: ﴿وَلْيَطَّوَّفُوا۟ بِٱلْبَيْتِ ٱلْعَتِيقِ﴾ (الحج: ٢٩)", explanation: "يُستفاد منه في باب الحج.", reference: "مراجع سُنّة" },
  { id: "1318", section: "الحج والعمرة", category: "الحج", level: "متوسط", question: "كم عدد أشواط السعي بين الصفا والمروة؟", answer: "سبعة أشواط، يبدأ بالصفا وينتهي بالمروة؛ فالذهاب من الصفا إلى المروة شوط، والرجوع من المروة إلى الصفا شوط ثانٍ", explanation: "يُستفاد منه في باب الحج.", reference: "مراجع سُنّة" },
  { id: "1319", section: "الحج والعمرة", category: "الحج", level: "سهل", question: "ما معنى الإحرام؟", answer: "نية الدخول في النسك (الحج أو العمرة). والتلبية عندها سنة مؤكدة عند الشافعية والحنابلة، وواجب عند المالكية، وشرطٌ لانعقاد الإحرام عند الحنفية فلا ينعقد عندهم إلا بها أو بما يقوم مقامها", explanation: "يُستفاد منه في باب الحج.", reference: "مراجع سُنّة" },
  { id: "1320", section: "الحج والعمرة", category: "الحج", level: "صعب", question: "ما الفرق بين القِران والتمتّع والإفراد في الحج؟", answer: "القِران: أن يُحرم بالحج والعمرة معًا بإحرام واحد. التمتّع: أن يُحرم بالعمرة أولاً فيتحلّل منها، ثم يُحرم بالحج في عامه. الإفراد: أن يُحرم بالحج وحده. ويلزم المتمتّع والقارن هَدْيٌ ولا هَدْيَ على المُفرِد، قال تعالى: ﴿فَمَن تَمَتَّعَ بِٱلْعُمْرَةِ إِلَى ٱلْحَجِّ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ﴾ (البقرة: ١٩٦)", explanation: "يُستفاد منه في باب الحج.", reference: "مراجع سُنّة" },
  { id: "1321", section: "الحج والعمرة", category: "الحج", level: "متوسط", question: "ما الإحصار في الحج؟", answer: "أن يُمنع المُحرِم من إتمام نسكه، فيتحلّل بنحر هَدْي، قال تعالى: ﴿فَإِنْ أُحْصِرْتُمْ فَمَا ٱسْتَيْسَرَ مِنَ ٱلْهَدْىِ﴾ (البقرة: ١٩٦). وقصره المالكية والشافعية على المنع بالعدوّ، ووسّعه الحنفية فأدخلوا فيه المرض وذهاب النفقة والحبس ونحوها", explanation: "يُستفاد منه في باب الحج.", reference: "مراجع سُنّة" },
  { id: "1322", section: "الحج والعمرة", category: "أركان الحج", level: "سهل", question: "ما أركان الحج الأساسية؟", answer: "الإحرام، والوقوف بعرفة، وطواف الإفاضة، والسعي بين الصفا والمروة", explanation: "يُستفاد منه في باب أركان الحج.", reference: "مراجع سُنّة" },
  { id: "1323", section: "الحج والعمرة", category: "مناسك الحج", level: "متوسط", question: "ما يوم عرفة ولماذا يُعدّ أهم أيام الحج؟", answer: "هو التاسع من ذي الحجة، وفيه الوقوف بعرفة الذي هو ركن الحج الأعظم، وصيامه يكفّر سنتين", explanation: "يُستفاد منه في باب مناسك الحج.", reference: "مراجع سُنّة" },
  { id: "1324", section: "الحج والعمرة", category: "مناسك الحج", level: "سهل", question: "ما الإحرام في الحج؟", answer: "هو النية لأداء نسك الحج أو العمرة مع ترك المحظورات، ويبدأ من الميقات المحدد لكل جهة", explanation: "يُستفاد منه في باب مناسك الحج.", reference: "مراجع سُنّة" },
  { id: "1325", section: "الحج والعمرة", category: "مناسك الحج", level: "صعب", question: "ما محظورات الإحرام؟", answer: "حلق الشعر، وتقليم الأظافر، ولبس المخيط للرجل، والطيب، والصيد، وعقد النكاح، والرفث", explanation: "يُستفاد منه في باب مناسك الحج.", reference: "مراجع سُنّة" },
  { id: "1326", section: "الحج والعمرة", category: "رمي الجمرات", level: "متوسط", question: "متى تُرمى جمرة العقبة؟", answer: "ترمى وحدها يوم النحر (العاشر من ذي الحجة)، ثم تُرمى مرة أخرى مع الجمرتين الصغرى والوسطى في كل يوم من أيام التشريق الثلاثة بعد زوال الشمس", explanation: "يُستفاد منه في باب رمي الجمرات.", reference: "مراجع سُنّة" },
  { id: "1327", section: "الحج والعمرة", category: "مواقيت الحج", level: "صعب", question: "ما مواقيت الحج الزمانية؟", answer: "شوال وذو القعدة وعشر من ذي الحجة، وهي أشهر الحج المذكورة في القرآن", explanation: "يُستفاد منه في باب مواقيت الحج.", reference: "مراجع سُنّة" },
  { id: "1328", section: "الحج والعمرة", category: "السعي", level: "سهل", question: "ما مكانة السعي بين الصفا والمروة؟", answer: "ركن من أركان الحج والعمرة لا يصح النسك بدونه، لقوله تعالى: ﴿إن الصفا والمروة من شعائر الله﴾", explanation: "يُستفاد منه في باب السعي.", reference: "مراجع سُنّة" },
  { id: "1329", section: "الحج والعمرة", category: "فريضة الحج", level: "سهل", question: "كم مرة حج النبي ﷺ؟ وما حجة الوداع؟", answer: "حج النبي ﷺ مرة واحدة بعد الهجرة وهي حجة الوداع عام 10هـ (632م)، وكان معه أكثر من مئة ألف من الصحابة. ألقى فيها خطبة الوداع الجامعة.", explanation: "يُستفاد منه في باب فريضة الحج.", reference: "مراجع سُنّة" },
  { id: "1330", section: "الحج والعمرة", category: "مناسك الحج", level: "متوسط", question: "ما الفرق بين الحج المفرد والقِران والتمتع؟", answer: "المفرد: الإحرام بالحج وحده من الميقات. القِران: الإحرام بالحج والعمرة معاً. التمتع: الإحرام بالعمرة أولاً ثم التحلل منها ثم الإحرام بالحج في أشهره. والثلاثة جائزة بالإجماع، وأفضلها محل خلاف بين المذاهب: الحنابلة يرون التمتع أفضل، والمالكية والشافعية يرون الإفراد أفضل، والحنفية يرون القِران أفضل.", explanation: "يُستفاد منه في باب مناسك الحج.", reference: "مراجع سُنّة" },
  { id: "1331", section: "الحج والعمرة", category: "أركان الحج", level: "متوسط", question: "ما أركان الحج التي لا يصح إلا بها؟", answer: "أركان الحج أربعة: 1- الإحرام (النية). 2- الوقوف بعرفة وهو أعظم الأركان («الحج عرفة»). 3- طواف الإفاضة (الزيارة). 4- السعي بين الصفا والمروة. وهذا مذهب الشافعية والحنابلة.", explanation: "يُستفاد منه في باب أركان الحج.", reference: "مراجع سُنّة" },
  { id: "1332", section: "الحج والعمرة", category: "الميقات", level: "متوسط", question: "ما ميقات أهل الكويت للحج والعمرة؟", answer: "ميقات أهل الكويت هو ذو الحليفة (أبيار علي) إذا مروا بطريق المدينة، أو ميقات قرن المنازل (السيل الكبير) إذا مروا بالطريق الشمالي السعودي الشرقي. وبعضهم يُحرم من الكويت إن نوى من الجو.", explanation: "يُستفاد منه في باب الميقات.", reference: "مراجع سُنّة" },
  { id: "1333", section: "علوم القرآن", category: "المكي والمدني", level: "سهل", question: "ما الفرق بين السور المكية والسور المدنية؟", answer: "المعتمد عند جمهور أهل العلم اعتبار زمن النزول: فالمكيّ ما نزل قبل هجرة النبي ﷺ ولو نزل بغير مكة، والمدنيّ ما نزل بعد الهجرة ولو نزل بمكة؛ ولذلك عُدّ قوله تعالى ﴿ٱلْيَوْمَ أَكْمَلْتُ لَكُمْ دِينَكُمْ﴾ [المائدة: 3] مدنيًّا وقد نزل بعرفة في حجة الوداع. وقيل في ضبطهما بالمكان (ما نزل بمكة وما نزل بالمدينة) وبالمخاطَبين (يا أيها الناس/يا أيها الذين آمنوا)، وكلاهما غير مطّرد", explanation: "يُستفاد منه في باب المكي والمدني.", reference: "مراجع سُنّة" },
  { id: "1334", section: "علوم القرآن", category: "السبع المثاني", level: "سهل", question: "ما السبع المثاني في قوله تعالى: ﴿وَلَقَدْ ءَاتَيْنَٰكَ سَبْعًۭا مِّنَ ٱلْمَثَانِى وَٱلْقُرْءَانَ ٱلْعَظِيمَ﴾ [الحجر: 87]؟", answer: "هي سورة الفاتحة، وهو الثابت المرفوع في حديث أبي سعيد بن المُعلّى رضي الله عنه أن النبي ﷺ قال له: «الحمد لله رب العالمين هي السبع المثاني والقرآن العظيم الذي أوتيته» (رواه البخاري في فضائل القرآن). وقيل: هي السبع الطُّوَل، ورُوي عن ابن مسعود وابن عباس رضي الله عنهم، والأول أصحّ لثبوته مرفوعًا. وأشهر ما قيل في وجه التسمية بالمثاني أنها تُثنى أي تُكرَّر في كل ركعة، وهو أحد أقوال أهل العلم", explanation: "يُستفاد منه في باب السبع المثاني.", reference: "مراجع سُنّة" },
  { id: "1335", section: "علوم القرآن", category: "جمع القرآن", level: "متوسط", question: "من تولى جمع القرآن الكريم في عهد أبي بكر الصديق رضي الله عنه؟", answer: "زيد بن ثابت الأنصاري رضي الله عنه؛ وكان ذلك بمشورة عمر بن الخطاب رضي الله عنه بعد استحرار القتل بالقُرّاء يوم اليمامة، فجُمع القرآن في صُحُف بقيت عند أبي بكر ثم عمر ثم حفصة بنت عمر رضي الله عنهم، والقصة في صحيح البخاري (٤٩٨٦). وهو غير جمع عثمان رضي الله عنه الذي نسخ منها المصاحف وأرسلها إلى الأمصار (البخاري ٤٩٨٧)", explanation: "يُستفاد منه في باب جمع القرآن.", reference: "مراجع سُنّة" },
  { id: "1336", section: "علوم القرآن", category: "جمع القرآن", level: "متوسط", question: "في عهد من تمّ توحيد المصحف وإرسال نسخ منه إلى الأمصار؟", answer: "في عهد عثمان بن عفان رضي الله عنه، فنُسخت المصاحف العثمانية وأُرسلت إلى الأمصار", explanation: "يُستفاد منه في باب جمع القرآن.", reference: "مراجع سُنّة" },
  { id: "1337", section: "علوم القرآن", category: "أسباب النزول", level: "متوسط", question: "ما المقصود بأسباب النزول؟", answer: "الحوادث والأسئلة والوقائع التي كانت سبباً في نزول آية أو آيات من القرآن الكريم", explanation: "يُستفاد منه في باب أسباب النزول.", reference: "مراجع سُنّة" },
  { id: "1338", section: "علوم القرآن", category: "إحصاءات القرآن", level: "سهل", question: "كم عدد أجزاء القرآن الكريم وكم عدد سوره؟", answer: "القرآن 30 جزءاً و114 سورة و6236 آية — إحصاءات القرآن الكريم المعتمدة.", explanation: "يُستفاد منه في باب إحصاءات القرآن.", reference: "مراجع سُنّة" },
  { id: "1339", section: "علوم القرآن", category: "المحكم والمتشابه", level: "صعب", question: "ما الفرق بين المحكم والمتشابه في القرآن الكريم؟", answer: "المحكم ما وضح معناه ولا يحتمل غيره، والمتشابه ما احتمل معاني متعددة ويحتاج إلى تدبر وتأويل", explanation: "يُستفاد منه في باب المحكم والمتشابه.", reference: "مراجع سُنّة" },
  { id: "1340", section: "علوم القرآن", category: "التفسير", level: "متوسط", question: "ما الفرق بين التفسير بالمأثور والتفسير بالرأي؟", answer: "التفسير بالمأثور: ما جاء عن النبي ﷺ والصحابة والتابعين. التفسير بالرأي: ما يُستنبَط بالاجتهاد والنظر مع الشروط العلمية", explanation: "يُستفاد منه في باب التفسير.", reference: "مراجع سُنّة" },
  { id: "1341", section: "علوم القرآن", category: "النسخ", level: "صعب", question: "ما النسخ في علوم القرآن؟", answer: "رفع حكم شرعي أو تلاوة بدليل شرعي متأخر، وله أنواع: نسخ الحكم دون التلاوة، ونسخ التلاوة دون الحكم، ونسخهما معاً", explanation: "يُستفاد منه في باب النسخ.", reference: "مراجع سُنّة" },
  { id: "1342", section: "علوم القرآن", category: "الإعجاز", level: "متوسط", question: "ما أنواع الإعجاز القرآني؟", answer: "الإعجاز البياني والبلاغي، والإعجاز التشريعي، والإعجاز العلمي، والإعجاز الغيبي، والإعجاز العددي عند بعض العلماء", explanation: "يُستفاد منه في باب الإعجاز.", reference: "مراجع سُنّة" },
  { id: "1343", section: "علوم القرآن", category: "أسباب النزول", level: "متوسط", question: "ما فائدة معرفة أسباب نزول القرآن؟", answer: "فهم الآيات وتفسيرها الصحيح، ومعرفة الحكمة من التشريع، وتحديد المقصود بالعام والخاص، ودفع الإشكالات", explanation: "يُستفاد منه في باب أسباب النزول.", reference: "مراجع سُنّة" },
  { id: "1344", section: "علوم القرآن", category: "الناسخ والمنسوخ", level: "صعب", question: "ما تعريف النسخ في القرآن الكريم؟", answer: "رفع الحكم الشرعي بدليل شرعي متأخر عنه. النسخ في القرآن نوعان: نسخ التلاوة دون الحكم، ونسخ الحكم دون التلاوة", explanation: "يُستفاد منه في باب الناسخ والمنسوخ.", reference: "مراجع سُنّة" },
  { id: "1345", section: "علوم القرآن", category: "المحكم والمتشابه", level: "متوسط", question: "ما الفرق بين المحكم والمتشابه في القرآن؟", answer: "المحكم: ما اتضح معناه ولا لبس فيه. المتشابه: ما خفي معناه واحتمل تأويلات. قال تعالى: هو الذي أنزل عليك الكتاب منه آيات محكمات هن أم الكتاب وأخر متشابهات", explanation: "يُستفاد منه في باب المحكم والمتشابه.", reference: "مراجع سُنّة" },
  { id: "1346", section: "علوم القرآن", category: "الإعجاز", level: "متوسط", question: "ما وجوه إعجاز القرآن الكريم؟", answer: "الإعجاز اللغوي والبياني، والإعجاز التشريعي، والإعجاز العلمي، والإعجاز الغيبي، والتحدي المستمر للإنس والجن على الإتيان بمثله", explanation: "يُستفاد منه في باب الإعجاز.", reference: "مراجع سُنّة" },
  { id: "1347", section: "علوم القرآن", category: "التفسير", level: "متوسط", question: "ما مناهج التفسير الرئيسية في علوم القرآن؟", answer: "التفسير بالمأثور (تفسير القرآن بالقرآن أو بالسنة أو بأقوال الصحابة)، والتفسير بالرأي (العقلي المنضبط)، والتفسير الموضوعي", explanation: "يُستفاد منه في باب التفسير.", reference: "مراجع سُنّة" },
  { id: "1348", section: "علوم القرآن", category: "القراءات", level: "صعب", question: "ما شروط القراءة الصحيحة المقبولة؟", answer: "ثلاثة شروط: موافقة أحد المصاحف العثمانية ولو احتمالاً، وصحة الإسناد، وموافقة وجه من أوجه العربية", explanation: "يُستفاد منه في باب القراءات.", reference: "مراجع سُنّة" },
  { id: "1349", section: "علوم القرآن", category: "السور", level: "سهل", question: "ما أقصر سورة في القرآن الكريم؟", answer: "سورة الكوثر — 3 آيات، وهي أقصر السور. سُمّيت بالكوثر لأن الله بشّر فيها النبي ﷺ بنهر الكوثر.", explanation: "يُستفاد منه في باب السور.", reference: "مراجع سُنّة" },
  { id: "1350", section: "علوم القرآن", category: "المكي والمدني", level: "متوسط", question: "ما ضابط السورة المكية والمدنية؟ وهل المعتبر المكان أم الزمان؟", answer: "الراجح: المعتبر الزمان؛ فالمكي ما نزل قبل الهجرة والمدني ما نزل بعدها. وفي كلٍّ ما نزل في مكة بعد الهجرة أو في السفر. قيل أيضاً: المعتبر المكان ابتداءً، والأقوال متعددة والأول أشهر.", explanation: "يُستفاد منه في باب المكي والمدني.", reference: "مراجع سُنّة" },
  { id: "1351", section: "علوم القرآن", category: "الناسخ والمنسوخ", level: "صعب", question: "هل يمكن نسخ القرآن بالسنة؟ اذكر موقف الجمهور.", answer: "الجمهور: لا يجوز نسخ القرآن بالسنة الآحادية، لقوله تعالى: ﴿مَا نَنسَخْ مِنْ آيَةٍ أَوْ نُنسِهَا نَأْتِ بِخَيْرٍ مِّنْهَا أَوْ مِثْلِهَا﴾ (البقرة: 106). وأجاز بعضهم النسخ بالسنة المتواترة.", explanation: "يُستفاد منه في باب الناسخ والمنسوخ.", reference: "مراجع سُنّة" },
  { id: "1352", section: "علوم القرآن", category: "القراءات", level: "متوسط", question: "ما شروط القراءة الصحيحة المقبولة التي ذكرها ابن الجزري؟", answer: "ثلاثة شروط: 1- موافقة وجه من وجوه العربية ولو احتمالاً. 2- موافقة رسم المصحف العثماني ولو تقديراً. 3- صحة السند إلى النبي ﷺ. فمتى اختل شرط منها ردت القراءة.", explanation: "يُستفاد منه في باب القراءات.", reference: "مراجع سُنّة" },
  { id: "1353", section: "علوم القرآن", category: "الإعجاز", level: "متوسط", question: "ما وجه الإعجاز البياني في القرآن الكريم؟", answer: "تحدّى القرآن الفصحاء بالإتيان بمثله ﴿قُل لَّئِنِ اجْتَمَعَتِ الْإِنسُ وَالْجِنُّ﴾ (الإسراء: 88). وجه الإعجاز: 1- التناسق البديع بين المعنى والإيقاع. 2- الإيجاز البالغ. 3- نظم فريد لا يُحاكى. 4- تأثيره في القلوب لدى من يسمعه بلا إكراه.", explanation: "يُستفاد منه في باب الإعجاز.", reference: "مراجع سُنّة" },
  { id: "1354", section: "علوم القرآن", category: "الجمع والتدوين", level: "متوسط", question: "من أول من جمع القرآن في مصحف واحد وما السبب في ذلك؟", answer: "أبو بكر الصديق رضي الله عنه بأمره ونظارة زيد بن ثابت. السبب: مقتل عدد كبير من حفّاظ القرآن في موقعة اليمامة (معركة القضاء على مسيلمة الكذاب) مما خشي عمر معه ضياع بعض القرآن.", explanation: "يُستفاد منه في باب الجمع والتدوين.", reference: "مراجع سُنّة" },
  { id: "1355", section: "علوم القرآن", category: "الأحرف السبعة", level: "صعب", question: "ما المقصود بالأحرف السبعة في الحديث النبوي؟", answer: "قال ﷺ: «أُنزل القرآن على سبعة أحرف» (البخاري). اختُلف في معناه على أربعين قولاً والراجح: سبعة أوجه يجوز أداء القرآن بها وكلها صحيح، توسعة على الأمة. وليست الأحرف السبعة هي القراءات السبع المشهورة.", explanation: "يُستفاد منه في باب الأحرف السبعة.", reference: "مراجع سُنّة" },
  { id: "1356", section: "علوم القرآن", category: "المكي والمدني", level: "متوسط", question: "ما الفرق بين السور المكية والمدنية؟ وما الضابط الأشهر عند العلماء؟", answer: "الضابط الأشهر: المكي ما نزل قبل الهجرة والمدني ما نزل بعدها بغض النظر عن مكان النزول. وثمة ضابط آخر: المكي ما فيه خطاب «يا أيها الناس» غالباً والمدني ما فيه «يا أيها الذين آمنوا». السور المكية أكثر تركيزاً على العقيدة والتوحيد والأخلاق، والمدنية تكثر فيها أحكام الفقه والتشريع.", explanation: "يُستفاد منه في باب المكي والمدني.", reference: "مراجع سُنّة" },
  { id: "1357", section: "علوم القرآن", category: "أقسام السور", level: "صعب", question: "ما تقسيم سور القرآن إلى طوال ومئين ومثاني ومفصّل؟", answer: "الطوال السبع: البقرة وآل عمران والنساء والمائدة والأنعام والأعراف ويونس (أو الأنفال والتوبة معاً). المئين: ما يقارب مئة آية أو يزيد. المثاني: ما دون المئة. المفصّل: من سورة ق إلى آخر القرآن، وسُمّي مفصّلاً لكثرة الفصل بين سوره بالبسملة.", explanation: "يُستفاد منه في باب أقسام السور.", reference: "مراجع سُنّة" },
  { id: "1358", section: "علوم القرآن", category: "أسباب النزول", level: "متوسط", question: "ما المقصود بأسباب النزول؟ ولماذا معرفتها مهمة؟", answer: "أسباب النزول هي الأحداث والأسئلة والوقائع التي نزلت الآيات في شأنها أو بسببها. ومعرفتها مهمة لأنها: تعين على فهم المعنى الصحيح، وتوضح الحكمة التشريعية، وتُزيل الإشكال في بعض الآيات، وتدفع توهم التعارض. والقاعدة الأصولية: «العبرة بعموم اللفظ لا بخصوص السبب».", explanation: "يُستفاد منه في باب أسباب النزول.", reference: "مراجع سُنّة" },
  { id: "1359", section: "علوم القرآن", category: "الناسخ والمنسوخ", level: "صعب", question: "ما تعريف النسخ في القرآن؟ وما أنواعه؟", answer: "النسخ: رفع الحكم الشرعي المتقدم بدليل شرعي متأخر. أنواعه: 1- نسخ التلاوة والحكم معاً (كآية الشيخ والشيخة على رأي بعضهم). 2- نسخ الحكم مع بقاء التلاوة كآيات تحريم الخمر التدريجي، ونسخ إلزام الثبات أمام عشرة أضعاف العدد (الأنفال: 65) إلى الثبات أمام ضعفين فقط (الأنفال: 66). 3- نسخ التلاوة مع بقاء الحكم. وللعلماء ضوابط صارمة في إثباته.", explanation: "يُستفاد منه في باب الناسخ والمنسوخ.", reference: "مراجع سُنّة" },
  { id: "1360", section: "علوم القرآن", category: "تقسيم المصحف", level: "سهل", question: "كم جزءاً وكم حزباً وكم ربعاً يتكون منه المصحف الشريف؟", answer: "يتكون المصحف من: 30 جزءاً، كل جزء حزبان فالجموع 60 حزباً، وكل حزب أربعة أرباع فالجموع 240 ربعاً. وهذا التقسيم وضعه العلماء لتيسير التلاوة والختم في ثلاثين يوماً.", explanation: "يُستفاد منه في باب تقسيم المصحف.", reference: "مراجع سُنّة" },
  { id: "1361", section: "الأذكار والأدعية", category: "الصباح والمساء", level: "سهل", question: "ما الذكر الجامع الوارد في الصباح؟", answer: "«أَصْبَحْنَا وَأَصْبَحَ الْمُلْكُ لِلَّهِ، وَالْحَمْدُ لِلَّهِ، لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ» (رواه مسلم)، وكان النبي ﷺ يقوله إذا أمسى بلفظ: «أمسينا وأمسى الملك لله». ولا يثبت ترتيب معيَّن يجعل ذكراً بعينه «أول» أذكار الصباح، وإنما هي أذكار مأثورة يقولها المسلم في وقتها", explanation: "يُستفاد منه في باب الصباح والمساء.", reference: "مراجع سُنّة" },
  { id: "1362", section: "الأذكار والأدعية", category: "الصباح والمساء", level: "متوسط", question: "ما الوارد في فضل قراءة آية الكرسي؟", answer: "أثبتُ ما ورد فيها أنها حِرزٌ عند النوم؛ ففي حديث أبي هريرة رضي الله عنه في قصة الشيطان الذي كان يأخذ من تمر الصدقة أنه قال له: «إذا أويتَ إلى فراشك فاقرأ آية الكرسي، لن يزال عليك من الله حافظ، ولا يقربك شيطان حتى تصبح»، فقال النبي ﷺ: «صدَقَك وهو كذوب» (رواه البخاري). وأمّا تخصيصها بالصباح والمساء فجاء من طرق أخرى تكلَّم أهل العلم في ثبوتها، والأصل المحفوظ في فضلها ما تقدَّم", explanation: "يُستفاد منه في باب الصباح والمساء.", reference: "مراجع سُنّة" },
  { id: "1363", section: "الأذكار والأدعية", category: "الصلاة", level: "سهل", question: "ما يُقال في الركوع؟", answer: "«سُبْحَانَ رَبِّيَ الْعَظِيمِ»؛ ثبت من فعله ﷺ في حديث حذيفة بن اليمان رضي الله عنه في وصف صلاته بالليل (رواه مسلم)، وأدنى الكمال ثلاث مرات. وهو واجب عند الحنابلة، سنة عند جمهور الفقهاء لا تبطل الصلاة بتركه", explanation: "يُستفاد منه في باب الصلاة.", reference: "مراجع سُنّة" },
  { id: "1364", section: "الأذكار والأدعية", category: "الصلاة", level: "سهل", question: "ما يُقال في السجود؟", answer: "«سُبْحَانَ رَبِّيَ الْأَعْلَى»؛ ثبت من فعله ﷺ في حديث حذيفة بن اليمان رضي الله عنه (رواه مسلم)، وأدنى الكمال ثلاث مرات. وحكمه كحكم تسبيح الركوع: واجب عند الحنابلة، سنة عند الجمهور. ويُستحب الإكثار من الدعاء في السجود لقوله ﷺ: «وأمّا السجود فاجتهدوا في الدعاء، فقَمِنٌ أن يُستجاب لكم» (رواه مسلم)", explanation: "يُستفاد منه في باب الصلاة.", reference: "مراجع سُنّة" }
];

